using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Text;
using System.Web;
using System.Web.Script.Serialization;
using System.Web.SessionState;
using SimsObject;

namespace InformationWeb.Dashboards.API
{
    /// <summary>
    /// API JSON dashboard tổng quan (/bang-dieu-khien.html).
    /// action=filters — Năm học / Khoa / Khóa
    /// action=data    — KPI tổng hợp + biểu đồ tóm tắt theo từng nhóm (DASH_MainSummary_GetData)
    /// </summary>
    public class HomeDashboardApi : IHttpHandler, IReadOnlySessionState
    {
        private const string PERMISSION_VIEW = "frmWebStudentList_View";
        private const string SP_DATA = "DASH_MainSummary_GetData";
        private const string SP_FILTER = "DASH_Overview_GetFilter";
        private const string SP_CLASS_SIZE = "DASH_StudentClassSize_GetData";
        private const string SP_FINANCE = "ACC_CongNoHocSinh_Dashboard_Web";
        private const string SP_ETHIC = "DASH_StudentEthic_GetData";
        private const string SP_SANCTION = "DASH_StudentSanction_GetData";
        private const string SP_REWARD = "DASH_StudentReward_GetData";

        public void ProcessRequest(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            if (!DashboardApiBase.EnsureLoggedIn(context))
                return;

            if (!WebGlobal.HasPermission(PERMISSION_VIEW))
            {
                WriteJson(context, false, "Bạn không có quyền xem bảng điều khiển.", null);
                return;
            }

            try
            {
                string strAction = GetRequestValue(context, "action");
                if (strAction != null && strAction.ToLower() == "filters")
                    HandleFilters(context);
                else
                    HandleData(context);
            }
            catch (Exception)
            {
                WriteJson(context, false, "Có lỗi xảy ra khi tải dữ liệu dashboard.", null);
            }
        }

        private void HandleFilters(HttpContext context)
        {
            string strListType = GetRequestValue(context, "listType");
            string strScienceId = GetRequestValue(context, "scienceId");

            if (strListType == null || strListType == "")
            {
                WriteJson(context, false, "Thiếu loại danh sách lọc.", null);
                return;
            }

            byte byListType = Convert.ToByte(strListType);
            SIM_Class objClass = new SIM_Class();
            DataTable dtbItems = objClass.GetDataTable(
                SP_FILTER,
                "@ScienceID", NormalizeFilter(strScienceId),
                "@ListType", byListType);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["items"] = DataTableToList(dtbItems);

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strSemester = GetRequestValue(context, "semester");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");

            object objYearId = DBNull.Value;
            object objSemester = DBNull.Value;

            if (strYearId != null && strYearId.Trim() != "" && strYearId != "0")
                objYearId = Convert.ToInt32(strYearId);

            if (strSemester != null && strSemester.Trim() != "" && strSemester != "0" && strSemester != "-1")
                objSemester = Convert.ToByte(strSemester);

            SIM_Class objClass = new SIM_Class();
            DataTable dtbMetrics = CallResultSetSafe(objClass, objYearId, objSemester, strScienceId, strCourseId, 1);

            if (dtbMetrics == null || dtbMetrics.Rows.Count == 0)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            List<Dictionary<string, object>> lstSections = BuildSections(dtbMetrics);
            AttachSectionCharts(lstSections, dtbMetrics, objYearId, objSemester, strScienceId, strCourseId);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["sections"] = lstSections;
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private void AttachSectionCharts(
            List<Dictionary<string, object>> lstSections,
            DataTable dtbMetrics,
            object yearId,
            object semester,
            string scienceId,
            string courseId)
        {
            int intIdx;
            for (intIdx = 0; intIdx < lstSections.Count; intIdx++)
            {
                Dictionary<string, object> dicSection = lstSections[intIdx];
                string strCode = Convert.ToString(dicSection["code"]);

                if (strCode == "overview")
                {
                    dicSection["charts"] = new List<Dictionary<string, object>>();
                    continue;
                }

                dicSection["charts"] = BuildChartsForSection(
                    strCode,
                    dtbMetrics,
                    yearId,
                    semester,
                    scienceId,
                    courseId);
            }
        }

        private List<Dictionary<string, object>> BuildChartsForSection(
            string sectionCode,
            DataTable dtbMetrics,
            object yearId,
            object semester,
            string scienceId,
            string courseId)
        {
            List<Dictionary<string, object>> lstCharts = new List<Dictionary<string, object>>();

            if (sectionCode == "classSize")
            {
                SIM_Class objClass = new SIM_Class();
                DataTable dtbStatus = CallClassSizeResultSetSafe(objClass, scienceId, courseId, 6);
                DataTable dtbScience = CallClassSizeResultSetSafe(objClass, scienceId, courseId, 5);

                lstCharts.Add(BuildChartFromTable(
                    "classSize_status",
                    "Phân bố trạng thái sinh viên",
                    "donut",
                    dtbStatus,
                    "StatusName",
                    "StudentCount"));

                lstCharts.Add(BuildChartFromTable(
                    "classSize_science",
                    "Sĩ số theo khoa / ngành",
                    "bar",
                    dtbScience,
                    "ScienceName",
                    "StudentCount"));
            }
            else if (sectionCode == "graduation")
            {
                long lngEligible = GetMetricRawLong(dtbMetrics, "graduation", "eligibleStudent");
                long lngNotEligible = GetMetricRawLong(dtbMetrics, "graduation", "notEligibleStudent");
                long lngGraduated = GetMetricRawLong(dtbMetrics, "graduation", "graduatedStudent");
                long lngReview = GetMetricRawLong(dtbMetrics, "graduation", "totalReviewStudent");
                long lngStudying = lngReview - lngGraduated;
                if (lngStudying < 0)
                    lngStudying = 0;

                lstCharts.Add(BuildChartFromPairs(
                    "graduation_eligible",
                    "Đủ / chưa đủ điều kiện tốt nghiệp",
                    "donut",
                    new string[] { "Đủ điều kiện", "Chưa đủ điều kiện" },
                    new long[] { lngEligible, lngNotEligible }));

                lstCharts.Add(BuildChartFromPairs(
                    "graduation_status",
                    "SV đã tốt nghiệp / đang học (xét TN)",
                    "donut",
                    new string[] { "Đã tốt nghiệp", "Đang học" },
                    new long[] { lngGraduated, lngStudying }));
            }
            else if (sectionCode == "finance")
            {
                SIM_Branch objBranch = new SIM_Branch();
                int? intYearId = ParseNullableInt(yearId);
                int? intSemester = ParseNullableInt(semester);

                DataTable dtbRatio = CallFinanceResultSetSafe(
                    objBranch, scienceId, courseId, intYearId, intSemester, 6);
                DataTable dtbScience = CallFinanceResultSetSafe(
                    objBranch, scienceId, courseId, intYearId, intSemester, 2);

                lstCharts.Add(BuildFinanceRatioChart(dtbRatio));
                lstCharts.Add(BuildChartFromTable(
                    "finance_science",
                    "Công nợ còn lại theo khoa",
                    "bar",
                    dtbScience,
                    "ScienceName",
                    "RemainMoney"));
            }
            else if (sectionCode == "ethic")
            {
                if (!HasYearSemester(yearId, semester))
                {
                    lstCharts.Add(BuildEmptyChart("ethic_level", "Phân bố xếp loại rèn luyện"));
                    lstCharts.Add(BuildEmptyChart("ethic_eval", "Tình trạng chấm điểm rèn luyện"));
                }
                else
                {
                    SIM_SummaryEthicMark objEthic = new SIM_SummaryEthicMark();
                    int intYear = Convert.ToInt32(yearId);
                    byte bySemester = Convert.ToByte(semester);

                    DataTable dtbLevel = CallEthicResultSetSafe(
                        objEthic, scienceId, courseId, intYear, bySemester, 2);
                    DataTable dtbEval = CallEthicResultSetSafe(
                        objEthic, scienceId, courseId, intYear, bySemester, 8);

                    lstCharts.Add(BuildChartFromTable(
                        "ethic_level",
                        "Phân bố xếp loại rèn luyện",
                        "donut",
                        dtbLevel,
                        "LevelName",
                        "StudentCount"));

                    lstCharts.Add(BuildChartFromTable(
                        "ethic_eval",
                        "Tình trạng chấm điểm rèn luyện",
                        "donut",
                        dtbEval,
                        "StatusName",
                        "StudentCount"));
                }
            }
            else if (sectionCode == "discipline")
            {
                if (!HasYearSemester(yearId, semester))
                {
                    lstCharts.Add(BuildEmptyChart("discipline_form", "Phân bố hình thức kỷ luật"));
                    lstCharts.Add(BuildEmptyChart("discipline_month", "Quyết định kỷ luật theo tháng"));
                }
                else
                {
                    SIM_Student objStudent = new SIM_Student();
                    int intYear = Convert.ToInt32(yearId);
                    byte bySemester = Convert.ToByte(semester);

                    DataTable dtbForm = CallSanctionResultSetSafe(
                        objStudent, scienceId, courseId, intYear, bySemester, 2);
                    DataTable dtbMonth = CallSanctionResultSetSafe(
                        objStudent, scienceId, courseId, intYear, bySemester, 3);

                    lstCharts.Add(BuildChartFromTable(
                        "discipline_form",
                        "Phân bố hình thức kỷ luật",
                        "donut",
                        dtbForm,
                        "SanctionFormName",
                        "SanctionCount"));

                    lstCharts.Add(BuildChartFromTable(
                        "discipline_month",
                        "Quyết định kỷ luật theo tháng",
                        "bar",
                        dtbMonth,
                        "MonthLabel",
                        "SanctionCount"));
                }
            }
            else if (sectionCode == "reward")
            {
                if (!HasYearSemester(yearId, semester))
                {
                    lstCharts.Add(BuildEmptyChart("reward_form", "Phân bố hình thức khen thưởng"));
                    lstCharts.Add(BuildEmptyChart("reward_month", "Quyết định khen thưởng theo tháng"));
                }
                else
                {
                    SIM_Student objStudent = new SIM_Student();
                    int intYear = Convert.ToInt32(yearId);
                    byte bySemester = Convert.ToByte(semester);

                    DataTable dtbForm = CallRewardResultSetSafe(
                        objStudent, scienceId, courseId, intYear, bySemester, 2);
                    DataTable dtbMonth = CallRewardResultSetSafe(
                        objStudent, scienceId, courseId, intYear, bySemester, 3);

                    lstCharts.Add(BuildChartFromTable(
                        "reward_form",
                        "Phân bố hình thức khen thưởng",
                        "donut",
                        dtbForm,
                        "SanctionFormName",
                        "SanctionCount"));

                    lstCharts.Add(BuildChartFromTable(
                        "reward_month",
                        "Quyết định khen thưởng theo tháng",
                        "bar",
                        dtbMonth,
                        "MonthLabel",
                        "SanctionCount"));
                }
            }
            else if (sectionCode == "teaching")
            {
                long lngTeacher = GetMetricRawLong(dtbMetrics, "teaching", "totalTeacher");
                long lngUnit = GetMetricRawLong(dtbMetrics, "teaching", "teachingUnit");
                long lngRegister = GetMetricRawLong(dtbMetrics, "teaching", "registerYear");
                long lngEnroll = GetMetricRawLong(dtbMetrics, "teaching", "enrollYear");
                long lngBooks = GetMetricRawLong(dtbMetrics, "teaching", "totalBooks");

                lstCharts.Add(BuildChartFromPairs(
                    "teaching_activity",
                    "Giảng dạy, tuyển sinh & thư viện",
                    "bar",
                    new string[] { "Giáo viên", "ĐVHT giảng dạy", "HS đăng ký (năm)", "HS nhập học (năm)", "Đầu sách TV" },
                    new long[] { lngTeacher, lngUnit, lngRegister, lngEnroll, lngBooks }));

                long lngMale = GetMetricRawLong(dtbMetrics, "classSize", "maleStudent");
                long lngFemale = GetMetricRawLong(dtbMetrics, "classSize", "femaleStudent");

                lstCharts.Add(BuildChartFromPairs(
                    "teaching_gender",
                    "Cơ cấu sinh viên nam / nữ (tham chiếu sĩ số)",
                    "donut",
                    new string[] { "Nam", "Nữ" },
                    new long[] { lngMale, lngFemale }));
            }

            return lstCharts;
        }

        private Dictionary<string, object> BuildFinanceRatioChart(DataTable dtbRatio)
        {
            decimal decReceipt = 0;
            decimal decRemain = 0;

            if (dtbRatio != null && dtbRatio.Rows.Count > 0)
            {
                DataRow drw = dtbRatio.Rows[0];
                decReceipt = GetRowDecimal(drw, "ReceiptMoney");
                decRemain = GetRowDecimal(drw, "RemainMoney");
            }

            return BuildChartFromPairs(
                "finance_ratio",
                "Tỷ lệ đã thu / còn nợ học phí",
                "donut",
                new string[] { "Đã thu", "Còn nợ" },
                new long[] { (long)decReceipt, (long)decRemain });
        }

        private Dictionary<string, object> BuildEmptyChart(string chartId, string title)
        {
            Dictionary<string, object> dicChart = new Dictionary<string, object>();
            dicChart["id"] = chartId;
            dicChart["title"] = title;
            dicChart["type"] = "donut";
            dicChart["items"] = new List<Dictionary<string, object>>();
            dicChart["empty"] = true;
            return dicChart;
        }

        private Dictionary<string, object> BuildChartFromTable(
            string chartId,
            string title,
            string chartType,
            DataTable dtb,
            string labelColumn,
            string valueColumn)
        {
            List<Dictionary<string, object>> lstItems = new List<Dictionary<string, object>>();

            if (dtb != null)
            {
                int intRow;
                for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
                {
                    DataRow drw = dtb.Rows[intRow];
                    string strLabel = GetRowString(drw, labelColumn);
                    decimal decValue = GetRowDecimal(drw, valueColumn);

                    if (strLabel == "" && decValue == 0)
                        continue;

                    Dictionary<string, object> dicItem = new Dictionary<string, object>();
                    dicItem["label"] = strLabel;
                    dicItem["value"] = decValue;
                    lstItems.Add(dicItem);
                }
            }

            Dictionary<string, object> dicChart = new Dictionary<string, object>();
            dicChart["id"] = chartId;
            dicChart["title"] = title;
            dicChart["type"] = chartType;
            dicChart["items"] = lstItems;
            dicChart["empty"] = lstItems.Count == 0;
            return dicChart;
        }

        private Dictionary<string, object> BuildChartFromPairs(
            string chartId,
            string title,
            string chartType,
            string[] arrLabels,
            long[] arrValues)
        {
            List<Dictionary<string, object>> lstItems = new List<Dictionary<string, object>>();
            int intIdx;

            if (arrLabels != null && arrValues != null)
            {
                int intLen = arrLabels.Length;
                if (arrValues.Length < intLen)
                    intLen = arrValues.Length;

                for (intIdx = 0; intIdx < intLen; intIdx++)
                {
                    Dictionary<string, object> dicItem = new Dictionary<string, object>();
                    dicItem["label"] = arrLabels[intIdx];
                    dicItem["value"] = arrValues[intIdx];
                    lstItems.Add(dicItem);
                }
            }

            Dictionary<string, object> dicChart = new Dictionary<string, object>();
            dicChart["id"] = chartId;
            dicChart["title"] = title;
            dicChart["type"] = chartType;
            dicChart["items"] = lstItems;
            dicChart["empty"] = lstItems.Count == 0 || IsAllZero(arrValues);
            return dicChart;
        }

        private bool IsAllZero(long[] arrValues)
        {
            if (arrValues == null || arrValues.Length == 0)
                return true;

            int intIdx;
            for (intIdx = 0; intIdx < arrValues.Length; intIdx++)
            {
                if (arrValues[intIdx] != 0)
                    return false;
            }
            return true;
        }

        private long GetMetricRawLong(DataTable dtbMetrics, string sectionGroup, string metricKey)
        {
            if (dtbMetrics == null)
                return 0;

            int intRow;
            for (intRow = 0; intRow < dtbMetrics.Rows.Count; intRow++)
            {
                DataRow drw = dtbMetrics.Rows[intRow];
                if (GetRowString(drw, "SectionGroup") != sectionGroup)
                    continue;
                if (GetRowString(drw, "MetricKey") != metricKey)
                    continue;

                return (long)GetRowDecimal(drw, "MetricValue");
            }
            return 0;
        }

        private decimal GetRowDecimal(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return 0;

            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return 0;

            decimal decValue;
            if (decimal.TryParse(drw[columnName].ToString(), out decValue))
                return decValue;

            return 0;
        }

        private bool HasYearSemester(object yearId, object semester)
        {
            if (yearId == null || yearId == DBNull.Value)
                return false;
            if (semester == null || semester == DBNull.Value)
                return false;
            return true;
        }

        private int? ParseNullableInt(object value)
        {
            if (value == null || value == DBNull.Value)
                return null;

            int intValue;
            if (int.TryParse(Convert.ToString(value), out intValue) && intValue > 0)
                return intValue;

            return null;
        }

        private DataTable CallClassSizeResultSetSafe(
            SIM_Class objClass,
            string scienceId,
            string courseId,
            byte resultSet)
        {
            try
            {
                return objClass.GetDataTable(
                    SP_CLASS_SIZE,
                    "@ScienceID", NormalizeFilter(scienceId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@ClassID", DBNull.Value,
                    "@ResultSet", resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private DataTable CallFinanceResultSetSafe(
            SIM_Branch objBranch,
            string scienceId,
            string courseId,
            int? yearId,
            int? semester,
            byte resultSet)
        {
            try
            {
                return objBranch.GetDataTable(
                    SP_FINANCE,
                    "@ScienceID", NormalizeFilter(scienceId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@ClassID", DBNull.Value,
                    "@YearID", yearId.HasValue ? (object)yearId.Value : DBNull.Value,
                    "@Semester", semester.HasValue ? (object)semester.Value : DBNull.Value,
                    "@ResultSet", resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private DataTable CallEthicResultSetSafe(
            SIM_SummaryEthicMark objEthic,
            string scienceId,
            string courseId,
            int yearId,
            byte semester,
            byte resultSet)
        {
            try
            {
                return objEthic.GetDataTable(
                    SP_ETHIC,
                    "@ScienceID", NormalizeFilter(scienceId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@ClassID", DBNull.Value,
                    "@YearID", yearId,
                    "@Semester", semester,
                    "@ResultSet", resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private DataTable CallSanctionResultSetSafe(
            SIM_Student objStudent,
            string scienceId,
            string courseId,
            int yearId,
            byte semester,
            byte resultSet)
        {
            try
            {
                return objStudent.GetDataTable(
                    SP_SANCTION,
                    "@ScienceID", NormalizeFilter(scienceId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@ClassID", DBNull.Value,
                    "@YearID", yearId,
                    "@Semester", semester,
                    "@ResultSet", resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private DataTable CallRewardResultSetSafe(
            SIM_Student objStudent,
            string scienceId,
            string courseId,
            int yearId,
            byte semester,
            byte resultSet)
        {
            try
            {
                return objStudent.GetDataTable(
                    SP_REWARD,
                    "@ScienceID", NormalizeFilter(scienceId),
                    "@CourseID", NormalizeFilter(courseId),
                    "@ClassID", DBNull.Value,
                    "@YearID", yearId,
                    "@Semester", semester,
                    "@ResultSet", resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private List<Dictionary<string, object>> BuildSections(DataTable dtbMetrics)
        {
            List<Dictionary<string, object>> lstSections = new List<Dictionary<string, object>>();
            Dictionary<string, Dictionary<string, object>> dicSectionMap = new Dictionary<string, Dictionary<string, object>>();
            Dictionary<string, List<Dictionary<string, object>>> dicMetricsMap = new Dictionary<string, List<Dictionary<string, object>>>();

            int intRow;
            for (intRow = 0; intRow < dtbMetrics.Rows.Count; intRow++)
            {
                DataRow drw = dtbMetrics.Rows[intRow];
                string strGroup = GetRowString(drw, "SectionGroup");
                if (strGroup == "")
                    continue;

                if (!dicSectionMap.ContainsKey(strGroup))
                {
                    Dictionary<string, object> dicSection = new Dictionary<string, object>();
                    dicSection["code"] = strGroup;
                    dicSection["title"] = GetRowString(drw, "SectionTitle");
                    dicSection["icon"] = GetSectionIcon(strGroup);
                    dicSectionMap[strGroup] = dicSection;
                    dicMetricsMap[strGroup] = new List<Dictionary<string, object>>();
                }

                Dictionary<string, object> dicMetric = new Dictionary<string, object>();
                dicMetric["key"] = GetRowString(drw, "MetricKey");
                dicMetric["label"] = GetRowString(drw, "MetricLabel");
                dicMetric["value"] = FormatMetricValue(GetRowString(drw, "MetricValue"));
                dicMetric["note"] = GetRowString(drw, "MetricNote");
                dicMetric["color"] = GetRowString(drw, "ColorClass");
                dicMetricsMap[strGroup].Add(dicMetric);
            }

            string[] arrOrder = new string[]
            {
                "overview",
                "classSize",
                "graduation",
                "finance",
                "ethic",
                "discipline",
                "reward",
                "teaching"
            };

            int intIdx;
            for (intIdx = 0; intIdx < arrOrder.Length; intIdx++)
            {
                string strCode = arrOrder[intIdx];
                if (!dicSectionMap.ContainsKey(strCode))
                    continue;

                Dictionary<string, object> dicSection = dicSectionMap[strCode];
                dicSection["metrics"] = dicMetricsMap[strCode];
                lstSections.Add(dicSection);
            }

            return lstSections;
        }

        private string GetSectionIcon(string sectionCode)
        {
            if (sectionCode == "overview")
                return "bi-speedometer2";
            if (sectionCode == "classSize")
                return "bi-door-open";
            if (sectionCode == "graduation")
                return "bi-mortarboard";
            if (sectionCode == "finance")
                return "bi-cash-stack";
            if (sectionCode == "ethic")
                return "bi-award";
            if (sectionCode == "discipline")
                return "bi-shield-exclamation";
            if (sectionCode == "reward")
                return "bi-trophy";
            if (sectionCode == "teaching")
                return "bi-book";
            return "bi-bar-chart";
        }

        private string FormatMetricValue(string rawValue)
        {
            if (rawValue == null || rawValue.Trim() == "")
                return "0";

            string strValue = rawValue.Trim();
            decimal decValue;
            if (strValue.IndexOf("%") >= 0)
            {
                string strNum = strValue.Replace("%", "").Trim();
                if (decimal.TryParse(strNum, out decValue))
                    return FormatNumber((long)decValue) + "%";
                return strValue;
            }

            if (decimal.TryParse(strValue, out decValue))
            {
                if (decValue >= 1000000000m)
                    return (decValue / 1000000000m).ToString("0.#") + " tỷ";
                if (decValue >= 1000000m)
                    return (decValue / 1000000m).ToString("0.#") + " tr";
                if (decValue >= 1000m && decValue == Math.Floor(decValue))
                    return FormatNumber((long)decValue);
                if (decValue == Math.Floor(decValue))
                    return FormatNumber((long)decValue);
                return decValue.ToString("0.#");
            }

            return strValue;
        }

        private DataTable CallResultSet(
            SIM_Class objClass,
            object yearId,
            object semester,
            string scienceId,
            string courseId,
            byte resultSet)
        {
            return objClass.GetDataTable(
                SP_DATA,
                "@YearID", yearId,
                "@Semester", semester,
                "@ScienceID", NormalizeFilter(scienceId),
                "@CourseID", NormalizeFilter(courseId),
                "@ResultSet", resultSet);
        }

        private DataTable CallResultSetSafe(
            SIM_Class objClass,
            object yearId,
            object semester,
            string scienceId,
            string courseId,
            byte resultSet)
        {
            try
            {
                return CallResultSet(objClass, yearId, semester, scienceId, courseId, resultSet);
            }
            catch (Exception)
            {
                return new DataTable();
            }
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private string GetRowString(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }

        private string FormatNumber(long value)
        {
            return value.ToString("#,##0").Replace(",", ".");
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }
    }
}

