    function formatNumber(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return val || "0";
        }
        return Math.round(num).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                if (window.DashboardApiUtils && window.DashboardApiUtils.redirectIfLoginRequired(response)) {
                    return;
                }
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function showState(state) {
        var loading = getEl("schDashStateLoading");
        var error = getEl("schDashStateError");
        var content = getEl("schDashContent");
        if (loading) {
            loading.className = state === "loading" ? "sch-dash-state" : "sch-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "sch-dash-state" : "sch-dash-state d-none";
        }
        if (content) {
            content.style.display = state === "ready" ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("schDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function getFilterValue(id) {
        var el = getEl(id);
        return el ? el.value : "";
    }

    function readFilters() {
        return {
            yearId: getFilterValue("schDashFilterYear"),
            semester: getFilterValue("schDashFilterSemester"),
            scienceId: getFilterValue("schDashFilterFaculty"),
            courseId: getFilterValue("schDashFilterCourse")
        };
    }

    function normalizeYearLabel(text) {
        return String(text || "").replace(/\s+/g, "").toLowerCase();
    }

    function setSelectByYearLabel(selectId, label) {
        var el = getEl(selectId);
        var i;
        var target = normalizeYearLabel(label);
        if (!el || target === "") {
            return false;
        }
        for (i = 0; i < el.options.length; i++) {
            if (normalizeYearLabel(el.options[i].text).indexOf(target) >= 0) {
                el.value = el.options[i].value;
                return true;
            }
        }
        return false;
    }

    function applyDefaultFilters() {
        var semesterEl = getEl("schDashFilterSemester");
        if (semesterEl) {
            semesterEl.value = DEFAULT_SEMESTER;
        }
        setSelectByYearLabel("schDashFilterYear", DEFAULT_YEAR_LABEL);
    }

    function fillSelect(id, rows, valueField, textField, defaultLabel, defaultValue) {
        var el = getEl(id);
        var i;
        var row;
        if (!el) {
            return;
        }
        while (el.options.length > 0) {
            el.remove(0);
        }
        el.appendChild(new Option(defaultLabel || "--Chọn--", defaultValue || ""));
        if (!rows || !rows.length) {
            return;
        }
        for (i = 0; i < rows.length; i++) {
            row = rows[i];
            if (!row || row[valueField] === null || row[valueField] === undefined) {
                continue;
            }
            el.appendChild(new Option(String(row[textField] || row[valueField]), String(row[valueField])));
        }
    }

    function loadFilterList(listType, scienceId, callback) {
        postJson({
            action: "filters",
            listType: listType,
            scienceId: scienceId || ""
        }, callback);
    }

    function loadYears(callback) {
        loadFilterList(0, "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterYear", data.items || [], "YearID", "YearName", "--Chọn--", "");
            callback(true, "");
        });
    }

    function loadSciences(callback) {
        loadFilterList(1, "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterFaculty", data.items || [], "ScienceID", "ScienceName", "Tất cả khoa", "");
            callback(true, "");
        });
    }

    function loadCourses(scienceId, callback) {
        loadFilterList(2, scienceId || "", function (ok, msg, data) {
            if (!ok) {
                callback(false, msg);
                return;
            }
            fillSelect("schDashFilterCourse", data.items || [], "CourseID", "CourseName", "Tất cả khóa", "");
            callback(true, "");
        });
    }

    function loadAllFilters(done) {
        loadYears(function (okYear, msgYear) {
            if (!okYear) {
                done(false, msgYear);
                return;
            }
            loadSciences(function (okScience, msgScience) {
                if (!okScience) {
                    done(false, msgScience);
                    return;
                }
                loadCourses("", function (okCourse, msgCourse) {
                    done(okCourse, msgCourse);
                });
            });
        });
    }

    function getMetricIcon(key) {
        return METRIC_ICONS[key] || "bi-hash";
    }

    function getColorClass(color) {
        var map = {
            teal: "scs-dash-kpi-teal",
            blue: "scs-dash-kpi-blue",
            orange: "scs-dash-kpi-orange",
            yellow: "scs-dash-kpi-yellow",
            green: "sch-dash-kpi-green",
            purple: "sch-dash-kpi-purple",
            red: "sch-dash-kpi-red"
        };
        return map[color] || "scs-dash-kpi-blue";
    }

    function destroyAllCharts() {
        var key;
        for (key in chartInstances) {
            if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                chartInstances[key].destroy();
            }
        }
        chartInstances = {};
    }

    function destroyChart(chartKey) {
        if (chartInstances[chartKey]) {
            chartInstances[chartKey].destroy();
            delete chartInstances[chartKey];
        }
    }

    function getChartItems(chart) {
        var items = chart && chart.items ? chart.items : [];
        var labels = [];
        var values = [];
        var i;
        for (i = 0; i < items.length; i++) {
            labels.push(items[i].label || "");
            values.push(parseFloat(items[i].value) || 0);
        }
        return { labels: labels, values: values };
    }

    function hasChartData(chart) {
        var parsed = getChartItems(chart);
        var i;
        if (!parsed.values.length) {
            return false;
        }
        for (i = 0; i < parsed.values.length; i++) {
            if (parsed.values[i] > 0) {
                return true;
            }
        }
        return chart && chart.empty !== true;
    }

    function getChartColors(chartId, count) {
        if (chartId === "finance_ratio") {
            return [SUCCESS, DANGER];
        }
        if (chartId === "graduation_eligible") {
            return [SUCCESS, WARNING];
        }
        if (chartId === "graduation_status") {
            return [PRIMARY, INFO];
        }
        if (chartId === "teaching_gender") {
            return [MALE_COLOR, FEMALE_COLOR];
        }
        var colors = [];
        var i;
        for (i = 0; i < count; i++) {
            colors.push(CHART_PALETTE[i % CHART_PALETTE.length]);
        }
        return colors;
    }

    function renderChart(chartKey, options) {
        var el = getEl(chartKey);
        if (!el || typeof ApexCharts === "undefined") {
            return;
        }
        destroyChart(chartKey);
        if (window.DashboardChartUtils) {
            window.DashboardChartUtils.enhanceBarDataLabels(options);
        }
        chartInstances[chartKey] = new ApexCharts(el, options);
        chartInstances[chartKey].render();
    }

    function buildDonutOptions(chart, parsed) {
        return {
            series: parsed.values,
            chart: Object.assign({}, baseChartOpts, {
                type: "donut",
                height: 300
            }),
            labels: parsed.labels,
            colors: getChartColors(chart.id, parsed.labels.length),
            legend: {
                position: "bottom",
                fontSize: "12px"
            },
            plotOptions: {
                pie: {
                    donut: {
                        size: "62%",
                        labels: {
                            show: true,
                            total: {
                                show: true,
                                label: "Tổng",
                                formatter: function (w) {
                                    var total = 0;
                                    var i;
                                    for (i = 0; i < w.globals.seriesTotals.length; i++) {
                                        total += w.globals.seriesTotals[i];
                                    }
                                    return formatNumber(total);
                                }
                            }
                        }
                    }
                }
            },
            dataLabels: {
                enabled: true,
                formatter: function (val) {
                    return Math.round(val) + "%";
                }
            }
        };
    }

    function buildBarOptions(chart, parsed) {
        var barHeight = Math.min(360, Math.max(280, parsed.labels.length * 36 + 60));
        return {
            series: [{ name: "Giá trị", data: parsed.values }],
            chart: Object.assign({}, baseChartOpts, {
                type: "bar",
                height: barHeight
            }),
            colors: getChartColors(chart.id, 1),
            plotOptions: {
                bar: {
                    horizontal: parsed.labels.length > 6,
                    borderRadius: 4,
                    dataLabels: { position: "top" }
                }
            },
            dataLabels: {
                enabled: true,
                formatter: function (val) {
                    return formatNumber(val);
                },
                offsetY: -18,
                style: { fontSize: "11px" }
            },
            xaxis: {
                categories: parsed.labels,
                labels: {
                    rotate: parsed.labels.length > 6 ? -35 : 0,
                    trim: true,
                    maxHeight: 80,
                    style: { fontSize: "11px" }
                }
            },
            yaxis: {
                labels: {
                    formatter: function (val) {
                        return formatNumber(val);
                    }
                }
            },
            grid: { padding: { left: 8, right: 8 } }
        };
    }

    function renderSectionCharts(section) {
        var charts = section.charts || [];
        var i;
        var chart;
        var parsed;
        var options;
        var emptyEl;
        var chartEl;

        for (i = 0; i < charts.length; i++) {
            chart = charts[i];
            if (!chart || !chart.id) {
                continue;
            }
            parsed = getChartItems(chart);
            emptyEl = getEl(chart.id + "_empty");
            chartEl = getEl(chart.id);

            if (!hasChartData(chart)) {
                destroyChart(chart.id);
                if (chartEl) {
                    chartEl.innerHTML = "";
                }
                if (emptyEl) {
                    emptyEl.className = "sch-dash-main-chart-empty";
                }
                continue;
            }

            if (emptyEl) {
                emptyEl.className = "sch-dash-main-chart-empty d-none";
            }

            if (chart.type === "bar") {
                options = buildBarOptions(chart, parsed);
            } else {
                options = buildDonutOptions(chart, parsed);
            }
            renderChart(chart.id, options);
        }
    }

    function buildChartCard(chart) {
        var emptyClass = "sch-dash-main-chart-empty d-none";
        return "<div class=\"col-12 col-lg-6 sch-dash-main-chart-col\">" +
            "<div class=\"sch-dash-card sch-dash-main-chart-card h-100\">" +
            "<div class=\"sch-dash-card-header\">" +
            "<h5>" + (chart.title || "") + "</h5>" +
            "</div>" +
            "<div class=\"sch-dash-card-body\">" +
            "<div class=\"sch-dash-chart-wrap sch-dash-main-chart-wrap\">" +
            "<div id=\"" + chart.id + "\"></div>" +
            "</div>" +
            "<div id=\"" + chart.id + "_empty\" class=\"" + emptyClass + "\">" +
            "<i class=\"bi bi-bar-chart-line me-1\"></i>Chưa có dữ liệu biểu đồ" +
            "</div>" +
            "</div></div></div>";
    }

    function buildChartsRow(section) {
        var charts = section.charts || [];
        var html = "";
        var i;

        if (section.code === "overview" || !charts.length) {
            return "";
        }

        html += "<div class=\"row sch-dash-row sch-dash-main-charts-row\">";
        for (i = 0; i < charts.length; i++) {
            html += buildChartCard(charts[i]);
        }
        html += "</div>";
        return html;
    }

    function buildMetricCard(metric) {
        var colorClass = getColorClass(metric.color);
        var iconClass = getMetricIcon(metric.key);
        var noteHtml = metric.note ? "<div class=\"sch-dash-main-kpi-note\">" + metric.note + "</div>" : "";
        return "<div class=\"col-12 col-sm-6 col-xl-3 sch-dash-kpi-col\">" +
            "<div class=\"sch-dash-card scs-dash-kpi-card sch-dash-main-kpi-card " + colorClass + "\">" +
            "<div class=\"scs-dash-kpi-inner d-flex align-items-center justify-content-between\">" +
            "<div class=\"scs-dash-kpi-main\">" +
            "<div class=\"scs-dash-kpi-head\">" +
            "<i class=\"bi " + iconClass + " scs-dash-kpi-head-icon\"></i>" +
            "<span class=\"scs-dash-kpi-title\">" + (metric.label || "") + "</span>" +
            "</div>" +
            "<div class=\"scs-dash-kpi-pill sch-dash-main-kpi-pill\">" +
            "<span class=\"sch-dash-kpi-value sch-dash-main-kpi-value\">" + (metric.value || "0") + "</span>" +
            "</div>" +
            noteHtml +
            "</div>" +
            "<div class=\"scs-dash-kpi-deco sch-dash-main-kpi-deco\" aria-hidden=\"true\">" +
            "<i class=\"bi " + iconClass + "\"></i>" +
            "</div>" +
            "</div></div></div>";
    }

    function buildSection(section) {
        var metrics = section.metrics || [];
        var html = "";
        var i;
        var sectionIcon = section.icon || DECO_ICONS[section.code] || "bi-bar-chart";

        html += "<div class=\"row sch-dash-row sch-dash-main-section\">";
        html += "<div class=\"col-12\">";
        html += "<div class=\"sch-dash-main-section-header\">";
        html += "<h5><i class=\"bi " + sectionIcon + " me-2\"></i>" + (section.title || "") + "</h5>";
        html += "</div></div></div>";

        html += "<div class=\"row sch-dash-row\">";
        for (i = 0; i < metrics.length; i++) {
            html += buildMetricCard(metrics[i]);
        }
        html += "</div>";

        html += buildChartsRow(section);
        return html;
    }

    function renderSections(sections) {
        var root = getEl("schDashSectionsRoot");
        var html = "";
        var i;

        if (!root) {
            return;
        }

        destroyAllCharts();
        sections = sections || [];
        lastSections = sections;

        for (i = 0; i < sections.length; i++) {
            html += buildSection(sections[i]);
        }

        root.innerHTML = html;

        for (i = 0; i < sections.length; i++) {
            if (sections[i].code !== "overview") {
                renderSectionCharts(sections[i]);
            }
        }
    }

    function updateTimestamp(text) {
        var el = getEl("schDashUpdateTime");
        if (!el) {
            return;
        }
        if (text) {
            el.textContent = text;
            return;
        }
        var now = new Date();
        var day = ("0" + now.getDate()).slice(-2);
        var month = ("0" + (now.getMonth() + 1)).slice(-2);
        var year = now.getFullYear();
        var hours = ("0" + now.getHours()).slice(-2);
        var minutes = ("0" + now.getMinutes()).slice(-2);
        el.textContent = day + "/" + month + "/" + year + " " + hours + ":" + minutes;
    }

    function applyPayload(data) {
        data = data || {};
        renderSections(data.sections);
        updateTimestamp(data.updatedAt);
    }

    function loadDashboardData() {
        var filters = readFilters();
        showState("loading");
        postJson({
            action: "data",
            yearId: filters.yearId,
            semester: filters.semester,
            scienceId: filters.scienceId,
            courseId: filters.courseId
        }, function (ok, msg, data) {
            if (!ok) {
                showState("error");
                setErrorMessage(msg);
                return;
            }
            showState("ready");
            applyPayload(data);
        });
    }

    function loadDashboard() {
        if (!filtersLoaded) {
            loadAllFilters(function (ok, msg) {
                filtersLoaded = true;
                if (!ok) {
                    showState("error");
                    setErrorMessage(msg);
                    return;
                }
                applyDefaultFilters();
                loadDashboardData();
            });
            return;
        }
        loadDashboardData();
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var refreshBtn = getEl("schDashBtnRefresh");
        var facultyEl = getEl("schDashFilterFaculty");
        var filters = document.querySelectorAll(".sch-dash-main-summary .sch-dash-filter-select");

        if (refreshBtn) {
            refreshBtn.addEventListener("click", function () {
                refreshBtn.classList.add("is-loading");
                loadDashboardData();
                setTimeout(function () {
