        var i;
        for (i = 0; i < filters.length; i++) {
            if (filters[i].id === "schDashFilterFaculty") {
                continue;
            }
            filters[i].addEventListener("change", function () {
                loadDashboardData();
            });
        }
    }

    function initSchoolDashboard() {
        if (!getEl("schDashBtnRefresh")) {
            return;
        }
        bindEvents();
        loadDashboard();
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initSchoolDashboard);
    } else {
        initSchoolDashboard();
    }
})();

